constraints:
1 <= n <= 10^{9}

expected time complexity: O(log_{10}(n))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def NthDigit(self, n):
		(cnt, r) = (0, 1)
		while True:
			cnt += r * pow(10, r - 1) * 9
			if cnt >= n:
				break
			r += 1
		cnt -= r * pow(10, r - 1) * 9
		n -= cnt
		(q, rem) = divmod(n, r)
		num = q + pow(10, r - 1) - 1
		if rem == 0:
			return num % 10
		else:
			num += 1
			ans = str(num)
			return int(ans[rem - 1])
